// Golden tests: our encodings must match upstream Syncthing's byte for byte (tests/golden/bep.txt is generated by
// tools/golden/main.go with upstream's own protobuf code), and decode back to the same values.
#include <fstream>
#include <map>
#include <sstream>

#include "core/bep.hpp"
#include "core/bep_frame.hpp"
#include "core/hello.hpp"
#include "test.hpp"

using namespace xst::bep;

namespace {

std::map<std::string, Bytes> golden()
{
	std::map<std::string, Bytes> out;
	std::ifstream in(XST_GOLDEN_DIR "/bep.txt");
	std::string name, hex;
	while (in >> name >> hex) {
		Bytes b;
		for (size_t i = 0; i + 1 < hex.size(); i += 2)
			b.push_back(static_cast<uint8_t>(std::stoi(hex.substr(i, 2), nullptr, 16)));
		out[name] = b;
	}
	return out;
}

Bytes seq(uint8_t start, size_t n)
{
	Bytes b(n);
	for (size_t i = 0; i < n; i++)
		b[i] = static_cast<uint8_t>(start + i);
	return b;
}

FileInfo golden_file()
{
	FileInfo f;
	f.name = "dir/file.txt";
	f.type = FileInfoType::file;
	f.size = 131072 + 5;
	f.permissions = 0644;
	f.modified_s = 1700000000;
	f.modified_ns = 123456789;
	f.modified_by = 0x5A5A5A5A5A5A5A5A;
	f.version.counters = { { 0x5A5A5A5A5A5A5A5A, 3 } };
	f.sequence = 7;
	f.block_size = 131072;
	f.blocks = { { 0, 131072, seq(0xA0, 32) }, { 131072, 5, seq(0xA0, 32) } };
	f.blocks_hash = seq(0xA0, 32);
	return f;
}

} // namespace

TEST(bep_golden_hello)
{
	xst::Hello h;
	h.device_name = "xbox";
	h.client_name = "xsyncthing";
	h.client_version = "v0.0.1";
	h.num_connections = 1;
	h.timestamp = 1700000000123456789;
	const auto frame = h.encode_frame();
	CHECK(Bytes(frame.begin() + 6, frame.end()) == golden().at("hello"));
}

TEST(bep_golden_cluster_config)
{
	ClusterConfig cc;
	Folder f;
	f.id = "abcd-1234";
	f.label = "Saves";
	Device d;
	d.id = seq(1, 32);
	d.name = "pc";
	d.addresses = { "dynamic", "tcp://192.168.1.2:22000" };
	d.max_sequence = 42;
	d.index_id = 0x1122334455667788;
	f.devices = { d };
	cc.folders = { f };
	const Bytes enc = encode(Message(cc));
	CHECK(enc == golden().at("cluster_config"));
	const auto back = decode(MessageType::cluster_config, enc);
	CHECK(back.has_value());
	const auto &bc = std::get<ClusterConfig>(*back);
	CHECK_EQ(bc.folders.size(), 1u);
	CHECK_EQ(bc.folders[0].devices[0].addresses.size(), 2u);
	CHECK_EQ(bc.folders[0].devices[0].index_id, 0x1122334455667788u);
	CHECK(encode(*back) == enc);
}

TEST(bep_golden_index)
{
	Index idx;
	idx.folder = "abcd-1234";
	idx.last_sequence = 7;
	FileInfo gone;
	gone.name = "gone";
	gone.deleted = true;
	gone.sequence = 6;
	gone.version.counters = { { 1, 9 } };
	idx.files = { golden_file(), gone };
	const Bytes enc = encode(Message(idx));
	CHECK(enc == golden().at("index"));
	const auto back = decode(MessageType::index, enc);
	CHECK(back.has_value());
	const auto &bi = std::get<Index>(*back);
	CHECK_EQ(bi.files.size(), 2u);
	CHECK_EQ(bi.files[0].blocks.size(), 2u);
	CHECK(bi.files[0].version == golden_file().version);
	CHECK(bi.files[1].deleted);
	CHECK(encode(*back) == enc);
}

TEST(bep_golden_small_messages)
{
	const auto g = golden();
	IndexUpdate iu;
	iu.folder = "f";
	iu.last_sequence = 9;
	iu.prev_sequence = 7;
	CHECK(encode(Message(iu)) == g.at("index_update"));

	Request rq;
	rq.id = 5;
	rq.folder = "abcd-1234";
	rq.name = "dir/file.txt";
	rq.offset = 131072;
	rq.size = 5;
	rq.hash = seq(0xA0, 32);
	rq.block_no = 1;
	CHECK(encode(Message(rq)) == g.at("request"));
	const auto rqb = decode(MessageType::request, g.at("request"));
	CHECK(rqb && std::get<Request>(*rqb).block_no == 1);

	Response rs;
	rs.id = 5;
	rs.data = { 'h', 'e', 'l', 'l', 'o' };
	CHECK(encode(Message(rs)) == g.at("response"));
	Response re;
	re.id = 6;
	re.code = ErrorCode::no_such_file;
	CHECK(encode(Message(re)) == g.at("response_err"));

	DownloadProgress dp;
	dp.folder = "f";
	FileDownloadProgressUpdate u;
	u.name = "a";
	u.block_indexes = { 0, 1, 200 };
	u.block_size = 131072;
	u.version.counters = { { 1, 2 } };
	dp.updates = { u };
	CHECK(encode(Message(dp)) == g.at("download_progress"));
	const auto dpb = decode(MessageType::download_progress, g.at("download_progress"));
	CHECK(dpb && std::get<DownloadProgress>(*dpb).updates[0].block_indexes == u.block_indexes);

	CHECK(encode(Message(Close{ "bye" })) == g.at("close"));
	CHECK(encode(Header{ MessageType::index, MessageCompression::lz4 }) == g.at("header_lz4"));
}

TEST(bep_frame_lz4_round_trip)
{
	Index idx;
	idx.folder = "folder";
	for (int i = 0; i < 50; i++) {
		FileInfo f = golden_file();
		f.name = "file-" + std::to_string(i);
		idx.files.push_back(f);
	}
	const auto framed = frame(Message(idx), CompressionPolicy::metadata);
	const size_t hlen = static_cast<size_t>(framed[0] << 8 | framed[1]);
	const auto header = decode_header(std::span(framed).subspan(2, hlen));
	CHECK(header && header->compression == MessageCompression::lz4);
	const auto body = std::span(framed).subspan(2 + hlen + 4);
	const auto back = unframe(*header, body);
	CHECK(back.has_value());
	CHECK_EQ(std::get<Index>(*back).files.size(), 50u);
	CHECK(encode(*back) == encode(Message(idx)));
}

TEST(bep_frame_response_not_compressed_with_metadata_policy)
{
	Response r;
	r.data.assign(4096, 'x');
	const auto framed = frame(Message(r), CompressionPolicy::metadata);
	const size_t hlen = static_cast<size_t>(framed[0] << 8 | framed[1]);
	const auto header = decode_header(std::span(framed).subspan(2, hlen));
	CHECK(header && header->compression == MessageCompression::none && header->type == MessageType::response);
}

TEST(bep_decode_rejects_bad_block_hash)
{
	FileInfo f = golden_file();
	f.blocks[0].hash.resize(5);
	Index idx;
	idx.files = { f };
	CHECK(!decode(MessageType::index, encode(Message(idx))));
}
